import{_ as t,o,c as p,a5 as a}from"./chunks/framework.BPFk9-tb.js";const u=JSON.parse('{"title":"写作课作业-078","description":"","frontmatter":{"date":"2020-10-22T15:22:43","title":"写作课作业-078","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[],"relativePath":"posts/homework/078.md","filePath":"posts/homework/078.md"}'),s={name:"posts/homework/078.md"};function r(_,e,c,l,n,i){return o(),p("div",null,[...e[0]||(e[0]=[a("<blockquote><p>10.5写作作业：《微信互联网平民创业》之《10. 连本地内容都做不好咋办?》</p></blockquote><blockquote><p>向上总是竞争越来越惨烈的;</p><p>向下总有越来越开阔的空间......</p></blockquote><p>退而求其次，再退而求其次，基于“长期价值”，找到适合自己的定位和机会。</p><blockquote><p>“客户终生价值”（Customer Lifetime Value，简称CLV）</p><p>所谓“客户终生价值”就是指你在一个购买你的商品或者服务的客户身上一辈子能赚到的利润。</p></blockquote><p>最终利润=CLV*客户数量</p><p>然后想到刘润《商业洞察力》里讲的“销售漏斗公式”：</p><p>销售=流量*转化率*客单价*复购率</p><p>然后再细看一下，这个两个公式居然是一样的。</p><p>CLV=客单价*复购率。</p><p>客户数量=流量*转化率。</p><p>今天和一个外贸的朋友聊天，他说，现在客户会先试个小单，如果一次产品不好，赔钱能解决倒还事小，很可能是这个客户再无机会了。这种情况客户终生价值就很小了。</p>",11)])])}const d=t(s,[["render",r]]);export{u as __pageData,d as default};
